using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OnNextCastDevotionOrbEffect", menuName = "Data/Battle/Effects/Orion/OnNextCastDevotionOrbEffect")]
public class OnNextCastDevotionOrbEffect : Effect
{
	private const string onNextCastDevotionOrbBaseID = "OnNextCastDevotionOrbBase";

	[Header("Description")]
	[SerializeField]
	private BattleAction battleAction;

	protected override string GetLocalizedDescription()
	{
		return Smart.Format(base.localizationManager.GetLocalizedString("OnNextCastDevotionOrbBase"), battleAction.GetActionDescription(LanguagesIndexes.IsCurrentLanguageLatinLanguage() ? (-4) : EffectsValues.NO_VALUE).LowercaseFirst().RemoveLast(), "{0}");
	}
}
